"use strict";(globalThis.webpackChunkmy_website||=[]).push([[20939],{76766(e){e.exports=JSON.parse('{"slug":"k-parameter","title":"k parameter","short":"The protocol parameter that sets the target number of saturated stake pools for healthy decentralization.","category":"consensus","aliases":["k","Desired Pool Count"],"mentalModel":null,"related":["pool-saturation","stake-pool","delegation","a0"],"sources":[],"link":null,"level":"advanced","body":"A network parameter that defines the target number of saturated stake pools. The protocol uses `k` to compute the saturation threshold (`total stake / k`); once a pool crosses that threshold, additional delegation yields diminishing returns, nudging delegators toward smaller pools.\\n\\nRaising `k` distributes stake across more pools and improves decentralization; lowering it concentrates stake in fewer, larger pools."}')}}]);